package com.mutang.xunxi;

import android.app.Activity;
import android.content.Intent;
import android.graphics.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.ByteBuffer;

/** Local square icon editor. Cancelling never replaces the existing icon. */
public final class IconCropActivity extends Activity {
    private Bitmap bitmap;private CropView crop;private View preview;private TextView status,confirm;private String sourceId;private boolean saving,active=true;
    private int dp(int n){return ReaderUi.dp(this,n);}
    private TextView label(String text,int size,int color){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(color);v.setIncludeFontPadding(false);return v;}
    @Override public void onCreate(Bundle state){
        super.onCreate(state);sourceId=getIntent().getStringExtra("source");android.net.Uri uri=getIntent().getData();if(sourceId==null||uri==null){finish();return;}
        getWindow().setStatusBarColor(MainActivity.BG);getWindow().setNavigationBarColor(MainActivity.BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(MainActivity.BG);root.setOnApplyWindowInsetsListener((v,i)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets p=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(p.left+dp(16),p.top+dp(10),p.right+dp(16),p.bottom+dp(12));}else v.setPadding(i.getSystemWindowInsetLeft()+dp(16),i.getSystemWindowInsetTop()+dp(10),i.getSystemWindowInsetRight()+dp(16),i.getSystemWindowInsetBottom()+dp(12));return i;});setContentView(root);
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView back=ReaderUi.button(this,"取消",false);back.setOnClickListener(v->{if(!saving)finish();});bar.addView(back);TextView title=label("裁剪网站图标",19,MainActivity.TEXT);title.setTypeface(Typeface.create("sans-serif-medium",0));title.setGravity(Gravity.CENTER);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));confirm=ReaderUi.button(this,"保存",true);confirm.setEnabled(false);confirm.setOnClickListener(v->save());bar.addView(confirm);root.addView(bar);
        TextView hint=label("拖动图片调整位置 · 双指缩放",13,MainActivity.MUTED);hint.setGravity(Gravity.CENTER);hint.setPadding(0,dp(15),0,dp(10));root.addView(hint);
        crop=new CropView();crop.setBackground(ReaderUi.shape(this,0xff1a2327,22));crop.setClipToOutline(true);root.addView(crop,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER_VERTICAL);controls.setPadding(0,dp(12),0,dp(8));String[] names={"缩小","放大","重置"};for(int j=0;j<names.length;j++){final int which=j;TextView b=ReaderUi.button(this,names[j],false);b.setOnClickListener(v->{if(crop.geometry==null)return;if(which==2)crop.geometry.reset();else crop.geometry.zoom(which==0?.8f:1.25f,crop.geometry.side/2,crop.geometry.side/2);crop.changed();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(j>0)p.setMargins(dp(7),0,0,0);controls.addView(b,p);}root.addView(controls);
        LinearLayout sample=new LinearLayout(this);sample.setGravity(Gravity.CENTER_VERTICAL);sample.setBackground(ReaderUi.shape(this,MainActivity.CARD,20));sample.setPadding(dp(15),dp(11),dp(15),dp(11));preview=new View(this){@Override protected void onDraw(Canvas c){if(bitmap==null||crop.geometry==null)return;crop.drawOutput(c,0,0,Math.min(getWidth(),getHeight()));}};preview.setBackground(ReaderUi.shape(this,MainActivity.PALE,15));preview.setClipToOutline(true);sample.addView(preview,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout words=new LinearLayout(this);words.setOrientation(1);words.setPadding(dp(12),0,0,0);words.addView(label("图标预览",15,MainActivity.TEXT));status=label("正在读取图片…",12,MainActivity.MUTED);status.setPadding(0,dp(5),0,0);words.addView(status);sample.addView(words,new LinearLayout.LayoutParams(0,-2,1));root.addView(sample);
        new Thread(()->{try{Bitmap loaded=load(uri);runOnUiThread(()->{if(!active){loaded.recycle();return;}bitmap=loaded;crop.initialize();if(state!=null&&crop.geometry!=null)crop.geometry.restore(state.getFloat("zoom",1),state.getFloat("cx",.5f),state.getFloat("cy",.5f));crop.changed();confirm.setEnabled(true);status.setText("确认后保存为正方形图标");});}catch(Exception e){runOnUiThread(()->{if(active)status.setText("无法读取图片，请返回重新选择");});}},"xunji-icon-preview").start();
    }
    Bitmap load(android.net.Uri uri)throws Exception{
        byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException();byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1){if(out.size()+n>24*1024*1024)throw new IOException("图片过大");out.write(buf,0,n);}bytes=out.toByteArray();}
        if(android.os.Build.VERSION.SDK_INT>=28){return ImageDecoder.decodeBitmap(ImageDecoder.createSource(ByteBuffer.wrap(bytes)),(decoder,info,source)->{android.util.Size s=info.getSize();int w=s.getWidth(),h=s.getHeight();if(w<=0||h<=0)throw new IllegalArgumentException();float scale=Math.min(1f,2048f/Math.max(w,h));decoder.setTargetSize(Math.max(1,Math.round(w*scale)),Math.max(1,Math.round(h*scale)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});}
        BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);if(opt.outWidth<=0||opt.outHeight<=0)throw new IOException();opt.inSampleSize=1;while(Math.max(opt.outWidth,opt.outHeight)/opt.inSampleSize>2048)opt.inSampleSize*=2;opt.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);if(b==null)throw new IOException();try{android.media.ExifInterface exif=new android.media.ExifInterface(new ByteArrayInputStream(bytes));int orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();switch(orientation){case 2:m.setScale(-1,1);break;case 3:m.setRotate(180);break;case 4:m.setScale(1,-1);break;case 5:m.setRotate(90);m.postScale(-1,1);break;case 6:m.setRotate(90);break;case 7:m.setRotate(-90);m.postScale(-1,1);break;case 8:m.setRotate(-90);break;}if(!m.isIdentity()){Bitmap rotated=Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),m,true);if(rotated!=b)b.recycle();b=rotated;}}catch(Exception ignored){}return b;
    }
    void save(){if(saving||bitmap==null||crop.geometry==null)return;boolean found=false;for(Store.Source s:new Store(this).sources())if(sourceId.equals(s.id)){found=true;break;}if(!found){Toast.makeText(this,"此订阅已删除",Toast.LENGTH_SHORT).show();finish();return;}Bitmap output=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);crop.drawOutput(new Canvas(output),0,0,256);saving=true;confirm.setEnabled(false);status.setText("正在保存…");new Thread(()->{try{SiteIcons.saveCropped(getApplicationContext(),sourceId,output);runOnUiThread(()->{if(active){setResult(RESULT_OK,new Intent().putExtra("source",sourceId));finish();}});}catch(Exception e){runOnUiThread(()->{if(active){saving=false;confirm.setEnabled(true);status.setText("保存失败，请重试");}});}finally{output.recycle();}},"xunji-icon-save").start();}
    @Override public void onBackPressed(){if(!saving)super.onBackPressed();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(crop!=null&&crop.geometry!=null){state.putFloat("zoom",crop.geometry.factor());state.putFloat("cx",crop.geometry.centerX());state.putFloat("cy",crop.geometry.centerY());}}
    @Override protected void onDestroy(){active=false;if(bitmap!=null)bitmap.recycle();super.onDestroy();}
    final class CropView extends View{
        CropGeometry geometry;float left,top,lastX,lastY;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);final ScaleGestureDetector scaleDetector;
        CropView(){super(IconCropActivity.this);setContentDescription("正方形图标裁剪框");scaleDetector=new ScaleGestureDetector(IconCropActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector d){if(geometry!=null){geometry.zoom(d.getScaleFactor(),d.getFocusX()-left,d.getFocusY()-top);changed();}return true;}});}
        void initialize(){if(bitmap==null||getWidth()<2||getHeight()<2)return;float zoom=geometry==null?1:geometry.factor(),cx=geometry==null?.5f:geometry.centerX(),cy=geometry==null?.5f:geometry.centerY();float side=Math.max(1,Math.min(getWidth(),getHeight())-dp(28));left=(getWidth()-side)/2;top=(getHeight()-side)/2;geometry=new CropGeometry(bitmap.getWidth(),bitmap.getHeight(),side);geometry.restore(zoom,cx,cy);}
        @Override protected void onSizeChanged(int w,int h,int oldW,int oldH){initialize();changed();}
        void changed(){invalidate();if(preview!=null)preview.invalidate();}
        void drawOutput(Canvas c,float x,float y,float size){if(geometry==null||bitmap==null)return;float ratio=size/geometry.side;c.save();c.clipRect(x,y,x+size,y+size);Matrix m=new Matrix();m.setScale(geometry.scale*ratio,geometry.scale*ratio);m.postTranslate(x+geometry.x*ratio,y+geometry.y*ratio);c.drawBitmap(bitmap,m,p);c.restore();}
        @Override protected void onDraw(Canvas c){super.onDraw(c);if(geometry==null||bitmap==null)return;float side=geometry.side,right=left+side,bottom=top+side;Matrix m=new Matrix();m.setScale(geometry.scale,geometry.scale);m.postTranslate(left+geometry.x,top+geometry.y);c.drawBitmap(bitmap,m,p);p.setColor(0xaa101719);p.setStyle(Paint.Style.FILL);c.drawRect(0,0,getWidth(),top,p);c.drawRect(0,bottom,getWidth(),getHeight(),p);c.drawRect(0,top,left,bottom,p);c.drawRect(right,top,getWidth(),bottom,p);p.setColor(0x99ffffff);p.setStrokeWidth(dp(1));for(int i=1;i<3;i++){float q=side*i/3;c.drawLine(left+q,top,left+q,bottom,p);c.drawLine(left,top+q,right,top+q,p);}p.setColor(0xffffffff);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));c.drawRect(left,top,right,bottom,p);p.setStyle(Paint.Style.FILL);p.setColor(0xffffffff);}
        @Override public boolean onTouchEvent(MotionEvent e){if(geometry==null)return true;scaleDetector.onTouchEvent(e);int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();return true;}if(a==MotionEvent.ACTION_POINTER_UP){int i=e.getActionIndex()==0?1:0;if(i<e.getPointerCount()){lastX=e.getX(i);lastY=e.getY(i);}return true;}if(a==MotionEvent.ACTION_MOVE&&!scaleDetector.isInProgress()&&e.getPointerCount()==1){float x=e.getX(),y=e.getY();geometry.pan(x-lastX,y-lastY);lastX=x;lastY=y;changed();}return true;}
    }
}
